33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Telephones;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    private final OwnerCreationAuditor ownerCreationAuditor;
73	
74	    private final WelcomeNotifier welcomeNotifier;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 OwnerCreationAuditor ownerCreationAuditor,
81	                                 WelcomeNotifier welcomeNotifier) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.ownerCreationAuditor = ownerCreationAuditor;
87	        this.welcomeNotifier = welcomeNotifier;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    /**
116	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that key
117	     * originally created, so a retried create with the same key returns that owner instead
118	     * of creating a duplicate. Held in memory for the application's lifetime and keyed by the
119	     * raw header value.
120	     */
121	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
126	        boolean hasKey = idempotencyKey != null && !idempotencyKey.isBlank();
127	        if (hasKey) {
128	            Integer existingId = idempotentCreates.get(idempotencyKey);
129	            if (existingId != null) {
130	                Owner existing = this.clinicService.findOwnerById(existingId);
131	                if (existing != null) {
132	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
133	                }
134	            }
135	        }
136	        ResponseEntity<OwnerDto> response = createNewOwner(ownerFieldsDto);
137	        if (hasKey && response.getStatusCode() == HttpStatus.CREATED
138	            && response.getBody() != null && response.getBody().getId() != null) {
139	            idempotentCreates.putIfAbsent(idempotencyKey, response.getBody().getId());
140	        }
141	        return response;
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
147	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
148	        if (currentOwner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        currentOwner.setAddress(ownerFieldsDto.getAddress());
152	        currentOwner.setCity(ownerFieldsDto.getCity());
153	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
154	        currentOwner.setLastName(ownerFieldsDto.getLastName());
155	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
156	        String email = ownerFieldsDto.getEmail();
157	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        owner.setDeleted(true);
171	        this.clinicService.saveOwner(owner);
172	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        HttpHeaders headers = new HttpHeaders();
183	        Pet pet = petMapper.toPet(petFieldsDto);
184	        owner.setId(ownerId);
185	        pet.setOwner(owner);
186	        pet.getType().setName(null);
187	        this.clinicService.savePet(pet);
188	        PetDto petDto = petMapper.toPetDto(pet);
189	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
190	            .buildAndExpand(pet.getId()).toUri());
191	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
197	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
198	        if (currentOwner != null) {
199	            Pet currentPet = this.clinicService.findPetById(petId);
200	            if (currentPet != null) {
201	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
202	                currentPet.setName(petFieldsDto.getName());
203	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
204	                this.clinicService.savePet(currentPet);
205	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
214	        HttpHeaders headers = new HttpHeaders();
215	        Visit visit = visitMapper.toVisit(visitFieldsDto);
216	        Pet pet = new Pet();
217	        pet.setId(petId);
218	        visit.setPet(pet);
