239	
240	    /**
241	     * Create and persist a brand-new owner from the supplied fields, returning the
242	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
243	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily
244	     * and city gates (each with its own rejection status), resolve any household,
245	     * {@link #assignDerivedAttributes derive the create-time attributes} (including the
246	     * household level ceiling that caps the owner's membership level), save, audit and
247	     * build the response with its {@code Location} header — so {@link #addOwner} itself
248	     * stays a thin entry point. An owner joining an existing household is admitted (its
249	     * membership level is capped to one above the household maximum rather than rejected):
250	     * two owners sharing a last name and postcode but with different telephones are no
251	     * longer a hard duplicate but a soft match. Duplicate detection is the single
252	     * {@link Owner#getIdentityKey() identity key}: a create whose identity key matches an
253	     * existing, non-deleted owner is rejected with {@code 409 Conflict}.
254	     *
255	     * @param ownerFieldsDto the owner fields from the request body
256	     * @return {@code 201 Created} with the created owner and its {@code Location} header,
257	     *         or the appropriate rejection status: {@code 400 Bad Request} when the fields
258	     *         are invalid, {@code 429 Too Many Requests} when the day's create cap is
259	     *         reached, or {@code 409 Conflict} when the city is at capacity or the owner's
260	     *         identity key duplicates an existing owner
261	     */
262	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
263	        HttpHeaders headers = new HttpHeaders();
264	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
265	        if (!normalizeNewOwner(owner)) {
266	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
267	        }
268	        if (dailyLimitReached(owner.getRegistrationDate())) {
269	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
270	        }
271	        if (cityIsAtCapacity(owner.getCity())) {
272	            return new ResponseEntity<>(HttpStatus.CONFLICT);
273	        }
274	        owner.setHouseholdId(owner.computeHouseholdId());
275	        if (isDuplicateIdentity(owner)) {
276	            return new ResponseEntity<>(HttpStatus.CONFLICT);
277	        }
278	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
279	        List<Owner> householdMembers = findHouseholdMembers(owner);
280	        boolean joinsExistingHousehold = !householdMembers.isEmpty();
281	        boolean declaredHouseholdMember = joinsExistingHousehold && sharesHousehold;
282	        assignDerivedAttributes(owner, declaredHouseholdMember, householdMembers);
283	        this.clinicService.saveOwner(owner);
284	        ownerCreationAuditor.auditOwnerCreated(owner);
285	        welcomeNotifier.enqueueWelcome(owner);
286	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
287	        headers.setLocation(UriComponentsBuilder.newInstance()
288	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
289	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
290	    }
291	
292	    /**
293	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
294	     * the canonical form each stored value must take: the address is trimmed,
295	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
296	     * telephone is converted to E.164, any email is lower-cased and a missing
297	     * registration date defaults to today. Field-level rejections are reported here
298	     * rather than inline in {@link #addOwner}, and normalisation runs before any
299	     * household comparison so those comparisons see the canonical values.
300	     *
301	     * @param owner the freshly-mapped owner to normalise
302	     * @return {@code true} if the fields are valid, or {@code false} if the address
303	     *         is blank after normalisation, the telephone cannot form a valid
304	     *         E.164 number, or a supplied registration date is later than the
305	     *         server date, in which case the request must be rejected with
306	     *         {@code 400 Bad Request}
307	     */
308	    private boolean normalizeNewOwner(Owner owner) {
309	        if (!normalizeAddressFields(owner)) {
310	            return false;
311	        }
312	        String telephone = Telephones.toE164(owner.getTelephone());
313	        if (telephone == null) {
314	            return false;
315	        }
316	        owner.setTelephone(telephone);
317	        if (owner.getEmail() != null) {
318	            String email = owner.getEmail().toLowerCase();
319	            owner.setEmail(email);
320	            if (Owner.emailDomainIsDisposable(email)) {
321	                return false;
322	            }
323	        }
324	        if (!owner.postcodeValidForLocality()) {
325	            return false;
326	        }
327	        if (owner.getRegistrationDate() == null) {
328	            owner.setRegistrationDate(LocalDate.now());
329	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
330	            return false;
331	        }
332	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
333	        return true;
334	    }
335	
336	    /**
337	     * Normalise the owner's address fields in place to their canonical stored form
338	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
339	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
340	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
341	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
342	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
343	     * them — the normalised {@code addressLine1}, with a single space and the normalised
344	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
345	     * flat {@code address} is normalised on its own, preserving backward compatibility.
346	     * Either way the canonicalised values are written back so every later household
347	     * comparison and read sees them.
348	     *
349	     * @param owner the freshly-mapped owner whose address fields are being normalised
350	     * @return {@code true} once an address is valid and stored, or {@code false} when
351	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
352	     *         present after normalisation, in which case the request must be rejected
353	     *         with {@code 400 Bad Request}
354	     */
355	    private boolean normalizeAddressFields(Owner owner) {
356	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
357	        if (!addressLine1.isEmpty()) {
358	            owner.setAddressLine1(addressLine1);
359	            String composed = addressLine1;
360	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
361	            if (!addressLine2.isEmpty()) {
362	                owner.setAddressLine2(addressLine2);
363	                composed = addressLine1 + " " + addressLine2;
364	            }
365	            owner.setAddress(composed);
366	            return true;
367	        }
368	        String address = Owner.normalizeAddress(owner.getAddress());
369	        if (address.isEmpty()) {
370	            return false;
371	        }
372	        owner.setAddress(address);
373	        return true;
374	    }
375	
376	    /**
377	     * The fixed list of public holidays on which the clinic is closed. A registration
378	     * date that lands on one of these dates is treated the same as a weekend and rolled
379	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
380	     */
381	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
382	        LocalDate.of(2026, 1, 1),
383	        LocalDate.of(2026, 1, 26),
384	        LocalDate.of(2026, 4, 25),
385	        LocalDate.of(2026, 12, 25),
386	        LocalDate.of(2026, 12, 28));
387	
388	    /**
389	     * Roll the given date forward to the next business day when it falls on a weekend or
390	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
391	     * at a time until a non-holiday weekday is reached, while a plain business day is
392	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
393	     * versa), the advance repeats until the date is neither. Applied to the effective
394	     * registration date (whether supplied in the request or defaulted to the server date)
395	     * so that every value derived from it uses the adjusted business day.
396	     *
397	     * @param date the effective registration date
398	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
399	     */
400	    private static LocalDate rollToBusinessDay(LocalDate date) {
401	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
402	            date = date.plusDays(1);
403	        }
404	        return date;
405	    }
406	
407	    /**
408	     * Whether the given date falls on a weekend (Saturday or Sunday).
409	     */
410	    private static boolean isWeekend(LocalDate date) {
411	        return switch (date.getDayOfWeek()) {
412	            case SATURDAY, SUNDAY -> true;
413	            default -> false;
414	        };
415	    }
416	
417	    /**
418	     * Find the existing owners that belong to the same household as the given owner,
419	     * i.e. share the same last name (compared case-insensitively with runs of
420	     * whitespace collapsed to a single space) and postcode, and so resolve to the same
421	     * deterministic {@code householdId}. Soft-deleted owners are excluded, so the result
422	     * holds only current household members. Evaluated before the new owner is saved, so
423	     * it reflects only owners that already existed at creation time; an owner joining no
424	     * existing household yields an empty list.
425	     *
426	     * @param owner the candidate owner being created
427	     * @return the current members of the owner's household, empty if none exists
428	     */
429	    private List<Owner> findHouseholdMembers(Owner owner) {
430	        return activeOwners()
431	            .filter(existing -> existing.sameHouseholdAs(owner))
432	            .toList();
433	    }
434	
435	    /**
436	     * Whether the candidate owner is a hard duplicate of an existing owner, i.e. it shares
437	     * the {@link Owner#getIdentityKey() identity key} (the SHA-256 digest over its
438	     * normalised telephone, lower-cased email and the Soundex of its last name) of a
439	     * current owner. Soft-deleted owners are ignored, so only the current owner population
440	     * is considered. A create whose identity key collides with an existing owner is
441	     * rejected with {@code 409 Conflict}. Evaluated after normalisation (so the
442	     * email-domain blocklist has already been applied) and before the owner is saved.
443	     *
444	     * @param owner the candidate owner being created, after normalisation
445	     * @return {@code true} if an existing, non-deleted owner shares the candidate's
446	     *         identity key
447	     */
448	    private boolean isDuplicateIdentity(Owner owner) {
449	        String identityKey = owner.getIdentityKey();
450	        return activeOwners()
451	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
452	    }
453	
454	    /**
455	     * The existing owners that are still active, i.e. those not flagged as soft-deleted.
456	     * Evaluated fresh against the saved owners each call, so it reflects only owners that
457	     * already existed at creation time; a soft-deleted owner is excluded and so takes no
458	     * part in the household resolution built on top of it. Isolating the exclusion here
459	     * keeps the "current owner population" one candidate is compared against in one place.
460	     *
461	     * @return a stream of the current, non-deleted owners
462	     */
463	    private Stream<Owner> activeOwners() {
464	        return this.clinicService.findAllOwners().stream()
465	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
466	    }
467	
468	    /**
469	     * Assign the owner's computed-at-creation attributes in place: its member id,
470	     * namesake count, bulk-signup warning and household size. Unlike
471	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
472	     * derived once here — from the owner's own (already normalised) fields and from the
473	     * wider owner population — and persisted with the owner. Run after normalisation,
474	     * household resolution and the identity-key check, so every value reflects the
475	     * owner's final field values and any household it has joined, and immediately before
476	     * the owner is saved.
477	     *
478	     * @param owner the candidate owner being created, after household resolution
479	     * @param declaredHouseholdMember whether this owner was created as a declared member
480	     *                                of an existing household (it shared an existing
481	     *                                owner's household and set {@code sharesHousehold}),
482	     *                                in which case it is not a suspected duplicate
483	     * @param householdMembers        the existing members of the owner's household at
484	     *                                creation time, used to derive its level ceiling
485	     */
486	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember,
487	            List<Owner> householdMembers) {
488	        owner.setMemberId(deduplicatedMemberId(owner));
489	        owner.setNamesakeCount(countNamesakes(owner));
490	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
491	        owner.setCapacityWarning(cityApproachingCapacity(owner.getCity()));
492	        owner.setHouseholdSize(householdSize(owner));
493	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
494	        assignPossibleDuplicate(owner, declaredHouseholdMember);
495	    }
496	
497	    /**
498	     * The household level ceiling to assign to the candidate owner: one above the highest
499	     * {@link Owner#getMembershipLevel() membership level} currently held by an existing
500	     * member of its household, or {@code null} when the household has no existing member
501	     * (so no ceiling applies). This bounds a new owner's reported membership level to at
502	     * most one above its household, keeping households from being outranked at the moment a
503	     * relative joins. Evaluated before the owner is saved, over the members that already
504	     * existed at creation time.
505	     *
506	     * @param householdMembers the existing members of the owner's household
507	     * @return the level ceiling to assign, or {@code null} when uncapped
508	     */
509	    private Integer membershipLevelCap(List<Owner> householdMembers) {
510	        return householdMembers.stream()
511	            .map(Owner::getMembershipLevel)
512	            .max(Comparator.naturalOrder())
513	            .map(max -> max + 1)
514	            .orElse(null);
515	    }
516	
517	    /**
518	     * Compute the member id to assign to the candidate owner, de-duplicated against
519	     * every existing owner's member id. The base id is the owner's computed
520	     * {@code <REGION><FY><HASH8><CHK>} (see {@link Owner#computeMemberId()}); when it does
521	     * not already belong to an existing owner it is used unchanged. Otherwise it collides,
522	     * and {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that
523	     * yields an id no existing owner holds, so the returned member id is unique. Evaluated
524	     * before the owner is saved, so only pre-existing owners are considered.
525	     *
526	     * @param owner the candidate owner being created, after normalisation
527	     * @return the unique (de-duplicated) member id to assign
528	     */
529	    private String deduplicatedMemberId(Owner owner) {
530	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
531	            .map(Owner::getMemberId)
532	            .filter(id -> id != null)
533	            .collect(java.util.stream.Collectors.toSet());
534	        String base = owner.computeMemberId();
535	        if (!existingIds.contains(base)) {
536	            return base;
537	        }
538	        int n = 2;
539	        while (existingIds.contains(base + "-" + n)) {
540	            n++;
541	        }
542	        return base + "-" + n;
543	    }
544	
545	    /**
546	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
547	     * match is an existing owner that shares this owner's last name (compared
548	     * case-insensitively) and postcode but carries a different (normalised) telephone.
549	     * When such a match exists the owner is still created, but with
550	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
551	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
552	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
553	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
554	     * are considered.
555	     *
556	     * <p>A declared household member — one that shared an existing owner's household
557	     * (same last name and postcode) and was admitted because it set
558	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
559	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
560	     *
561	     * @param owner the candidate owner being created, after household resolution
562	     * @param declaredHouseholdMember whether the owner is a declared household member
563	     */
564	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
565	        if (declaredHouseholdMember) {
566	            owner.setPossibleDuplicate(false);
567	            owner.setPossibleDuplicateOf(null);
568	            return;
569	        }
570	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
571	            .filter(existing -> isSoftMatch(owner, existing))
572	            .min(Comparator.comparing(Owner::getId));
573	        if (match.isPresent()) {
574	            owner.setPossibleDuplicate(true);
575	            owner.setPossibleDuplicateOf(match.get().getId());
576	        } else {
577	            owner.setPossibleDuplicate(false);
578	            owner.setPossibleDuplicateOf(null);
579	        }
580	    }
581	
582	    /**
583	     * Whether an already-created {@code existing} owner is a soft-match for the candidate
584	     * {@code owner}: their {@link Owner#getIdentityKey() identity keys} differ (so they are
585	     * not a hard duplicate) yet the {@link Owner#soundex(String) Soundex} of their last
586	     * names and their postcodes match. This is the single soft-match test
587	     * {@link #assignPossibleDuplicate} applies across the owner population, isolated here so
588	     * the comparison that decides a suspected duplicate lives in one place. Two owners
589	     * sharing a last name and postcode but with different telephones therefore soft-match
590	     * rather than being rejected, since the telephone is part of the identity key.
591	     *
592	     * @param owner    the candidate owner being created
593	     * @param existing an already-created owner to test against it
594	     * @return {@code true} if {@code existing} is a soft-match for the candidate
595	     */
596	    private boolean isSoftMatch(Owner owner, Owner existing) {
597	        String postcode = owner.getPostcode();
598	        return postcode != null && postcode.equals(existing.getPostcode())
599	            && Owner.soundex(owner.getLastName()).equals(Owner.soundex(existing.getLastName()))
600	            && !owner.getIdentityKey().equals(existing.getIdentityKey());
601	    }
602	
603	    /**
604	     * Count how many owners belong to the given owner's household once this create
605	     * completes: the owners that already share its deterministic {@code householdId}
606	     * (derived from last name and postcode) plus the owner being created. Evaluated
607	     * after the owner's {@code householdId} has been assigned. An owner whose
608	     * {@code householdId} matches no existing owner is a household of one.
609	     *
610	     * @param owner the candidate owner being created, after household resolution
611	     * @return the household member count after this create (at least {@code 1})
612	     */
613	    private int householdSize(Owner owner) {
614	        String householdId = owner.getHouseholdId();
615	        if (householdId == null) {
616	            return 1;
617	        }
618	        long existing = this.clinicService.findAllOwners().stream()
619	            .filter(other -> householdId.equals(other.getHouseholdId()))
620	            .count();
621	        return (int) existing + 1;
622	    }
623	
624	    /**
625	     * Count the existing owners that share the given owner's first and last name,
626	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
627	     * before the new owner is saved, so the result reflects only owners that
628	     * already existed at creation time.
629	     *
630	     * @param owner the candidate owner being created
631	     * @return the number of existing namesakes
632	     */
633	    private int countNamesakes(Owner owner) {
634	        String firstName = normalizeName(owner.getFirstName());
635	        String lastName = normalizeName(owner.getLastName());
636	        return (int) this.clinicService.findAllOwners().stream()
637	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
638	                && normalizeName(existing.getLastName()).equals(lastName))
639	            .count();
640	    }
641	
642	    private static String normalizeName(String value) {
643	        return value == null ? "" : value.trim().toLowerCase();
644	    }
645	
646	    /**
647	     * Determine whether the given city has already reached its owner capacity, i.e.
648	     * it already contains 50 or more existing owners (compared case-insensitively
649	     * with surrounding whitespace trimmed). A new owner may not be created in a city
650	     * that is at capacity.
651	     *
652	     * @param city the candidate owner's city
653	     * @return {@code true} if the city already holds 50 or more owners
654	     */
655	    private boolean cityIsAtCapacity(String city) {
656	        return ownersInCity(city) >= 50;
657	    }
658	
659	    /**
660	     * Determine whether the given city is approaching its owner capacity, i.e. it
661	     * already contains between 40 and 49 existing owners (compared case-insensitively
662	     * with surrounding whitespace trimmed). This warns that the capacity limit of 50
663	     * is near; the hard rejection at 50 is handled separately by
664	     * {@link #cityIsAtCapacity(String)}. Evaluated before the new owner is saved, so
665	     * it reflects only owners that already existed at creation time.
666	     *
667	     * @param city the candidate owner's city
668	     * @return {@code true} if the city already holds between 40 and 49 owners
669	     */
670	    private boolean cityApproachingCapacity(String city) {
671	        long count = ownersInCity(city);
672	        return count >= 40 && count < 50;
673	    }
674	
675	    /**
676	     * Count the existing owners in the given city, compared case-insensitively with
677	     * surrounding whitespace trimmed.
678	     *
679	     * @param city the city to count owners for
680	     * @return the number of existing owners in that city
681	     */
682	    private long ownersInCity(String city) {
683	        String normalizedCity = normalizeName(city);
684	        return this.clinicService.findAllOwners().stream()
685	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
686	            .count();
687	    }
688	
689	    /**
690	     * Determine whether the daily owner-creation limit has already been reached, i.e.
691	     * 100 or more owners already carry the given registration date. A new owner may
692	     * not be created once that day's cap is reached.
693	     *
694	     * @param registrationDate the registration date the new owner would be created with
695	     * @return {@code true} if 100 or more existing owners share that registration date
696	     */
697	    private boolean dailyLimitReached(LocalDate registrationDate) {
698	        long count = this.clinicService.findAllOwners().stream()
699	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
700	            .count();
701	        return count >= 100;
702	    }
703	
704	    /**
705	     * Determine whether more than 80 owners have already been created for the given
706	     * registration date, i.e. strictly more than 80 existing owners carry that date.
707	     * Evaluated before the new owner is saved, so it reflects only owners that
708	     * already existed at creation time.
709	     *
710	     * @param registrationDate the registration date the new owner would be created with
711	     * @return {@code true} if more than 80 existing owners share that registration date
712	     */
713	    private boolean bulkSignupWarning(LocalDate registrationDate) {
714	        long count = this.clinicService.findAllOwners().stream()
715	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
716	            .count();
717	        return count > 80;
718	    }
719	}
